// Raw Doppler Speed
class Cat007I120Rds {
public:
    const uint8& rep() const { return rep_; }
    uint8& mutable_rep() { return rep_; }
    void set_rep(const uint8& v) { rep_ = v; }

    const std::vector<Cat007I120Rds_dopplerElement>& doppler() const { return doppler_; }
    std::vector<Cat007I120Rds_dopplerElement>& mutable_doppler() { return doppler_; }
    void set_doppler(const std::vector<Cat007I120Rds_dopplerElement>& v) { doppler_ = v; }

    bool operator==(const Cat007I120Rds&) const = default;

    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        w.write_u8(static_cast<uint8_t>(static_cast<uint8>(doppler_.size())));
        for (const auto& elem : doppler_) {
            CONDUIT_TRY(elem.encode(w));
        }
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<Cat007I120Rds> decode(conduit::io::BitReader& r) {
        Cat007I120Rds result;
        {
            auto val = r.read_u8();
            if (!val) return std::unexpected(val.error().with_context("field 'rep'"));
            result.rep_ = static_cast<uint8>(*val);
        }
        {
            auto count = static_cast<size_t>(result.rep_);
            if (count > static_cast<size_t>(INT32_MAX)) return std::unexpected(conduit::Error(conduit::ErrorCode::InvalidArgument, "invalid array count").with_context("array 'doppler'"));
            result.doppler_.reserve(count);
            for (size_t i = 0; i < count; i++) {
                auto elem = Cat007I120Rds_dopplerElement::decode(r);
                if (!elem) return std::unexpected(elem.error().with_context("array 'doppler'"));
                result.doppler_.push_back(std::move(*elem));
            }
        }
        return result;
    }

    std::string to_string(std::span<const std::pair<std::string, std::string>> overrides) const {
        (void)overrides;
        std::ostringstream oss;
        oss << "Cat007I120Rds{"
            << "rep=" << +(rep_)
            << ", doppler=["
            ;
            for (size_t i = 0; i < doppler_.size(); ++i) {
                if (i > 0) oss << ", ";
                oss << doppler_[i].to_string();
            }
            oss << "]"
            << "}";
        return oss.str();
    }
    std::string to_string() const { return to_string({}); }

private:
    uint8 rep_{};
    std::vector<Cat007I120Rds_dopplerElement> doppler_{};
};

class Cat007I120_sub {
public:
    bool has_cal() const { return cal_.has_value(); }
    const Cat007I120Cal& cal() const { return cal_.value(); }
    Cat007I120Cal& mutable_cal() { if (!cal_) cal_.emplace(); return *cal_; }
    void set_cal(const Cat007I120Cal& v) { cal_ = v; }
    void clear_cal() { cal_.reset(); }

    bool has_rds() const { return rds_.has_value(); }
    const Cat007I120Rds& rds() const { return rds_.value(); }
    Cat007I120Rds& mutable_rds() { if (!rds_) rds_.emplace(); return *rds_; }
    void set_rds(const Cat007I120Rds& v) { rds_ = v; }
    void clear_rds() { rds_.reset(); }

    bool operator==(const Cat007I120_sub&) const = default;

    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        int last_octet = 0;
        if (cal_.has_value() && 0 > last_octet) last_octet = 0;
        if (rds_.has_value() && 0 > last_octet) last_octet = 0;
        std::array<uint8_t, 1> fspec{};
        if (cal_.has_value()) fspec[0] |= (1 << 7);
        if (rds_.has_value()) fspec[0] |= (1 << 6);
        for (size_t i = 0; i < static_cast<size_t>(last_octet); i++) fspec[i] |= (1 << 0);
        w.write_bytes(std::span<const uint8_t>(fspec.data(), static_cast<size_t>(last_octet) + 1));
        if (cal_.has_value()) {
            CONDUIT_TRY(cal_->encode(w));
        }
        if (rds_.has_value()) {
            CONDUIT_TRY(rds_->encode(w));
        }
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<Cat007I120_sub> decode(conduit::io::BitReader& r) {
        Cat007I120_sub result;

        // Read FSPEC bitmap
        std::array<uint8_t, 1> fspec{};
        size_t fspec_len = 0;
        while (true) {
            auto byte = r.read_u8();
            if (!byte) return std::unexpected(byte.error());
            if (fspec_len < 1) fspec[fspec_len] = *byte;
            fspec_len++;
            if (!(*byte & (1 << 0))) break;
        }

        if (fspec_len > 0 && (fspec[0] & (1 << 7))) {
            auto val = Cat007I120Cal::decode(r);
            if (!val) return std::unexpected(val.error());
            result.cal_ = std::move(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 6))) {
            auto val = Cat007I120Rds::decode(r);
            if (!val) return std::unexpected(val.error());
            result.rds_ = std::move(*val);
        }

        return result;
    }

    std::string to_string() const {
        std::ostringstream oss;
        oss << "Cat007I120_sub{";
        bool first = true;
        if (cal_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "cal=" << (*cal_).to_string();
        }
        if (rds_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "rds=" << (*rds_).to_string();
        }
        oss << "}";
        return oss.str();
    }

private:
    std::optional<Cat007I120Cal> cal_;
    std::optional<Cat007I120Rds> rds_;
};

