class Cat007I415_sub {
public:
    bool has_rim() const { return rim_.has_value(); }
    const Cat007I415Rim& rim() const { return rim_.value(); }
    Cat007I415Rim& mutable_rim() { if (!rim_) rim_.emplace(); return *rim_; }
    void set_rim(const Cat007I415Rim& v) { rim_ = v; }
    void clear_rim() { rim_.reset(); }

    bool has_mipt() const { return mipt_.has_value(); }
    const uint8& mipt() const { return mipt_.value(); }
    uint8& mutable_mipt() { if (!mipt_) mipt_.emplace(); return *mipt_; }
    void set_mipt(const uint8& v) { mipt_ = v; }
    void clear_mipt() { mipt_.reset(); }

    bool operator==(const Cat007I415_sub&) const = default;

    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        int last_octet = 0;
        if (rim_.has_value() && 0 > last_octet) last_octet = 0;
        if (mipt_.has_value() && 0 > last_octet) last_octet = 0;
        std::array<uint8_t, 1> fspec{};
        if (rim_.has_value()) fspec[0] |= (1 << 2);
        if (mipt_.has_value()) fspec[0] |= (1 << 1);
        for (size_t i = 0; i < static_cast<size_t>(last_octet); i++) fspec[i] |= (1 << 0);
        w.write_bytes(std::span<const uint8_t>(fspec.data(), static_cast<size_t>(last_octet) + 1));
        if (rim_.has_value()) {
            CONDUIT_TRY(rim_->encode(w));
        }
        if (mipt_.has_value()) {
            w.write_bits(*mipt_, 8);
        }
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<Cat007I415_sub> decode(conduit::io::BitReader& r) {
        Cat007I415_sub result;

        // Read FSPEC bitmap
        std::array<uint8_t, 1> fspec{};
        size_t fspec_len = 0;
        while (true) {
            auto byte = r.read_u8();
            if (!byte) return std::unexpected(byte.error());
            if (fspec_len < 1) fspec[fspec_len] = *byte;
            fspec_len++;
            if (!(*byte & (1 << 0))) break;
        }

        if (fspec_len > 0 && (fspec[0] & (1 << 2))) {
            auto val = Cat007I415Rim::decode(r);
            if (!val) return std::unexpected(val.error());
            result.rim_ = std::move(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 1))) {
            auto val = r.read_bits(8);
            if (!val) return std::unexpected(val.error());
            result.mipt_ = static_cast<uint8>(*val);
        }

        return result;
    }

    std::string to_string() const {
        std::ostringstream oss;
        oss << "Cat007I415_sub{";
        bool first = true;
        if (rim_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "rim=" << (*rim_).to_string();
        }
        if (mipt_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "mipt=" << static_cast<uint64_t>(*mipt_);
        }
        oss << "}";
        return oss.str();
    }

private:
    std::optional<Cat007I415Rim> rim_;
    std::optional<uint8> mipt_;
};

