class Cat021I110Tid {
public:
    const uint8& rep() const { return rep_; }
    uint8& mutable_rep() { return rep_; }
    void set_rep(const uint8& v) { rep_ = v; }

    const std::vector<Cat021I110Tid_pointsElement>& points() const { return points_; }
    std::vector<Cat021I110Tid_pointsElement>& mutable_points() { return points_; }
    void set_points(const std::vector<Cat021I110Tid_pointsElement>& v) { points_ = v; }

    bool operator==(const Cat021I110Tid&) const = default;

    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        w.write_u8(static_cast<uint8_t>(static_cast<uint8>(points_.size())));
        for (const auto& elem : points_) {
            CONDUIT_TRY(elem.encode(w));
        }
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<Cat021I110Tid> decode(conduit::io::BitReader& r) {
        Cat021I110Tid result;
        {
            auto val = r.read_u8();
            if (!val) return std::unexpected(val.error().with_context("field 'rep'"));
            result.rep_ = static_cast<uint8>(*val);
        }
        {
            auto count = static_cast<size_t>(result.rep_);
            if (count > static_cast<size_t>(INT32_MAX)) return std::unexpected(conduit::Error(conduit::ErrorCode::InvalidArgument, "invalid array count").with_context("array 'points'"));
            result.points_.reserve(count);
            for (size_t i = 0; i < count; i++) {
                auto elem = Cat021I110Tid_pointsElement::decode(r);
                if (!elem) return std::unexpected(elem.error().with_context("array 'points'"));
                result.points_.push_back(std::move(*elem));
            }
        }
        return result;
    }

    std::string to_string(std::span<const std::pair<std::string, std::string>> overrides) const {
        (void)overrides;
        std::ostringstream oss;
        oss << "Cat021I110Tid{"
            << "rep=" << +(rep_)
            << ", points=["
            ;
            for (size_t i = 0; i < points_.size(); ++i) {
                if (i > 0) oss << ", ";
                oss << points_[i].to_string();
            }
            oss << "]"
            << "}";
        return oss.str();
    }
    std::string to_string() const { return to_string({}); }

private:
    uint8 rep_{};
    std::vector<Cat021I110Tid_pointsElement> points_{};
};

class Cat021I110_sub {
public:
    bool has_tis() const { return tis_.has_value(); }
    const Cat021I110Tis& tis() const { return tis_.value(); }
    Cat021I110Tis& mutable_tis() { if (!tis_) tis_.emplace(); return *tis_; }
    void set_tis(const Cat021I110Tis& v) { tis_ = v; }
    void clear_tis() { tis_.reset(); }

    bool has_tid() const { return tid_.has_value(); }
    const Cat021I110Tid& tid() const { return tid_.value(); }
    Cat021I110Tid& mutable_tid() { if (!tid_) tid_.emplace(); return *tid_; }
    void set_tid(const Cat021I110Tid& v) { tid_ = v; }
    void clear_tid() { tid_.reset(); }

    bool operator==(const Cat021I110_sub&) const = default;

    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        int last_octet = 0;
        if (tis_.has_value() && 0 > last_octet) last_octet = 0;
        if (tid_.has_value() && 0 > last_octet) last_octet = 0;
        std::array<uint8_t, 1> fspec{};
        if (tis_.has_value()) fspec[0] |= (1 << 7);
        if (tid_.has_value()) fspec[0] |= (1 << 6);
        for (size_t i = 0; i < static_cast<size_t>(last_octet); i++) fspec[i] |= (1 << 0);
        w.write_bytes(std::span<const uint8_t>(fspec.data(), static_cast<size_t>(last_octet) + 1));
        if (tis_.has_value()) {
            CONDUIT_TRY(tis_->encode(w));
        }
        if (tid_.has_value()) {
            CONDUIT_TRY(tid_->encode(w));
        }
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<Cat021I110_sub> decode(conduit::io::BitReader& r) {
        Cat021I110_sub result;

        // Read FSPEC bitmap
        std::array<uint8_t, 1> fspec{};
        size_t fspec_len = 0;
        while (true) {
            auto byte = r.read_u8();
            if (!byte) return std::unexpected(byte.error());
            if (fspec_len < 1) fspec[fspec_len] = *byte;
            fspec_len++;
            if (!(*byte & (1 << 0))) break;
        }

        if (fspec_len > 0 && (fspec[0] & (1 << 7))) {
            auto val = Cat021I110Tis::decode(r);
            if (!val) return std::unexpected(val.error());
            result.tis_ = std::move(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 6))) {
            auto val = Cat021I110Tid::decode(r);
            if (!val) return std::unexpected(val.error());
            result.tid_ = std::move(*val);
        }

        return result;
    }

    std::string to_string() const {
        std::ostringstream oss;
        oss << "Cat021I110_sub{";
        bool first = true;
        if (tis_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "tis=" << (*tis_).to_string();
        }
        if (tid_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "tid=" << (*tid_).to_string();
        }
        oss << "}";
        return oss.str();
    }

private:
    std::optional<Cat021I110Tis> tis_;
    std::optional<Cat021I110Tid> tid_;
};

