class Cat048I130_sub {
public:
    bool has_srl() const { return srl_.has_value(); }
    const uint8& srl() const { return srl_.value(); }
    uint8& mutable_srl() { if (!srl_) srl_.emplace(); return *srl_; }
    void set_srl(const uint8& v) { srl_ = v; }
    void clear_srl() { srl_.reset(); }

    bool has_srr() const { return srr_.has_value(); }
    const uint8& srr() const { return srr_.value(); }
    uint8& mutable_srr() { if (!srr_) srr_.emplace(); return *srr_; }
    void set_srr(const uint8& v) { srr_ = v; }
    void clear_srr() { srr_.reset(); }

    bool has_sam() const { return sam_.has_value(); }
    const int8& sam() const { return sam_.value(); }
    int8& mutable_sam() { if (!sam_) sam_.emplace(); return *sam_; }
    void set_sam(const int8& v) { sam_ = v; }
    void clear_sam() { sam_.reset(); }

    bool has_prl() const { return prl_.has_value(); }
    const uint8& prl() const { return prl_.value(); }
    uint8& mutable_prl() { if (!prl_) prl_.emplace(); return *prl_; }
    void set_prl(const uint8& v) { prl_ = v; }
    void clear_prl() { prl_.reset(); }

    bool has_pam() const { return pam_.has_value(); }
    const int8& pam() const { return pam_.value(); }
    int8& mutable_pam() { if (!pam_) pam_.emplace(); return *pam_; }
    void set_pam(const int8& v) { pam_ = v; }
    void clear_pam() { pam_.reset(); }

    bool has_rpd() const { return rpd_.has_value(); }
    const int8& rpd() const { return rpd_.value(); }
    int8& mutable_rpd() { if (!rpd_) rpd_.emplace(); return *rpd_; }
    void set_rpd(const int8& v) { rpd_ = v; }
    void clear_rpd() { rpd_.reset(); }

    bool has_apd() const { return apd_.has_value(); }
    const int8& apd() const { return apd_.value(); }
    int8& mutable_apd() { if (!apd_) apd_.emplace(); return *apd_; }
    void set_apd(const int8& v) { apd_ = v; }
    void clear_apd() { apd_.reset(); }

    bool operator==(const Cat048I130_sub&) const = default;

    conduit::VoidResult encode(conduit::io::BitWriter& w) const {
        int last_octet = 0;
        if (srl_.has_value() && 0 > last_octet) last_octet = 0;
        if (srr_.has_value() && 0 > last_octet) last_octet = 0;
        if (sam_.has_value() && 0 > last_octet) last_octet = 0;
        if (prl_.has_value() && 0 > last_octet) last_octet = 0;
        if (pam_.has_value() && 0 > last_octet) last_octet = 0;
        if (rpd_.has_value() && 0 > last_octet) last_octet = 0;
        if (apd_.has_value() && 0 > last_octet) last_octet = 0;
        std::array<uint8_t, 1> fspec{};
        if (srl_.has_value()) fspec[0] |= (1 << 7);
        if (srr_.has_value()) fspec[0] |= (1 << 6);
        if (sam_.has_value()) fspec[0] |= (1 << 5);
        if (prl_.has_value()) fspec[0] |= (1 << 4);
        if (pam_.has_value()) fspec[0] |= (1 << 3);
        if (rpd_.has_value()) fspec[0] |= (1 << 2);
        if (apd_.has_value()) fspec[0] |= (1 << 1);
        for (size_t i = 0; i < static_cast<size_t>(last_octet); i++) fspec[i] |= (1 << 0);
        w.write_bytes(std::span<const uint8_t>(fspec.data(), static_cast<size_t>(last_octet) + 1));
        if (srl_.has_value()) {
            w.write_bits(*srl_, 8);
        }
        if (srr_.has_value()) {
            w.write_bits(*srr_, 8);
        }
        if (sam_.has_value()) {
            w.write_signed_bits(*sam_, 8);
        }
        if (prl_.has_value()) {
            w.write_bits(*prl_, 8);
        }
        if (pam_.has_value()) {
            w.write_signed_bits(*pam_, 8);
        }
        if (rpd_.has_value()) {
            w.write_signed_bits(*rpd_, 8);
        }
        if (apd_.has_value()) {
            w.write_signed_bits(*apd_, 8);
        }
        if (w.has_error()) return std::unexpected(w.error());
        return {};
    }

    static conduit::Result<Cat048I130_sub> decode(conduit::io::BitReader& r) {
        Cat048I130_sub result;

        // Read FSPEC bitmap
        std::array<uint8_t, 1> fspec{};
        size_t fspec_len = 0;
        while (true) {
            auto byte = r.read_u8();
            if (!byte) return std::unexpected(byte.error());
            if (fspec_len < 1) fspec[fspec_len] = *byte;
            fspec_len++;
            if (!(*byte & (1 << 0))) break;
        }

        if (fspec_len > 0 && (fspec[0] & (1 << 7))) {
            auto val = r.read_bits(8);
            if (!val) return std::unexpected(val.error());
            result.srl_ = static_cast<uint8>(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 6))) {
            auto val = r.read_bits(8);
            if (!val) return std::unexpected(val.error());
            result.srr_ = static_cast<uint8>(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 5))) {
            auto val = r.read_signed_bits(8);
            if (!val) return std::unexpected(val.error());
            result.sam_ = static_cast<int8>(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 4))) {
            auto val = r.read_bits(8);
            if (!val) return std::unexpected(val.error());
            result.prl_ = static_cast<uint8>(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 3))) {
            auto val = r.read_signed_bits(8);
            if (!val) return std::unexpected(val.error());
            result.pam_ = static_cast<int8>(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 2))) {
            auto val = r.read_signed_bits(8);
            if (!val) return std::unexpected(val.error());
            result.rpd_ = static_cast<int8>(*val);
        }
        if (fspec_len > 0 && (fspec[0] & (1 << 1))) {
            auto val = r.read_signed_bits(8);
            if (!val) return std::unexpected(val.error());
            result.apd_ = static_cast<int8>(*val);
        }

        return result;
    }

    std::string to_string() const {
        std::ostringstream oss;
        oss << "Cat048I130_sub{";
        bool first = true;
        if (srl_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "srl=" << static_cast<uint64_t>(*srl_);
        }
        if (srr_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "srr=" << static_cast<uint64_t>(*srr_);
        }
        if (sam_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "sam=" << static_cast<int64_t>(*sam_);
        }
        if (prl_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "prl=" << static_cast<uint64_t>(*prl_);
        }
        if (pam_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "pam=" << static_cast<int64_t>(*pam_);
        }
        if (rpd_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "rpd=" << static_cast<int64_t>(*rpd_);
        }
        if (apd_.has_value()) {
            if (!first) oss << ", ";
            first = false;
            oss << "apd=" << static_cast<int64_t>(*apd_);
        }
        oss << "}";
        return oss.str();
    }

private:
    std::optional<uint8> srl_;
    std::optional<uint8> srr_;
    std::optional<int8> sam_;
    std::optional<uint8> prl_;
    std::optional<int8> pam_;
    std::optional<int8> rpd_;
    std::optional<int8> apd_;
};

